\begin{tikzpicture}[x=0.65cm,y=1.3cm]
\definecolor{cosBlue}{HTML}{268CFF}
\definecolor{houseGrid}{HTML}{CCCCCC}
\definecolor{absoluteRed}{HTML}{EF6068}
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\path[use as bounding box] (-10.2,-2.6) rectangle (12,2.8);
\draw[step=1,white,opacity=0] (-9.4248,-2) grid (9.4248,2);
\foreach \k in {-6,-5,...,6} {\draw[houseGrid,line width=0.25pt] ({\k*pi/2},-2.2)--({\k*pi/2},2.2);}
\foreach \j in {-2,-1,1,2} {\draw[houseGrid,line width=0.25pt] (-9.4248,\j)--(9.4248,\j);}
\draw[->,line width=0.5pt] (-9.7,0)--(10.0,0) node[right] {$x$};
\draw[->,line width=0.5pt] (0,-2.3)--(0,2.5) node[above] {$y$};
\foreach \k/\lab in {-3/{-3\pi},-2/{-2\pi},-1/{-\pi},1/{\pi},2/{2\pi},3/{3\pi}} {\draw[line width=0.4pt] ({\k*pi},-0.06)--({\k*pi},0.06);\node[below] at ({\k*pi},-0.08) {\special{dvisvgm:raw <g data-graph-text="tick">}$\lab$\special{dvisvgm:raw </g>}};}
\foreach \j in {-2,-1,1,2} {\draw[line width=0.4pt] (-0.08,\j)--(0.08,\j);\node[left] at (-0.1,\j) {\special{dvisvgm:raw <g data-graph-text="tick">}$\j$\special{dvisvgm:raw </g>}};}
\draw[cosBlue,line width=0.8pt,domain=-9.424778:9.424778,samples=241] plot (\x,{cos(\x r)});
\draw[<->,absoluteRed,line width=0.8pt] ({pi-5.6},1.4)--({pi},0)--({pi+5.6},1.4);
\fill[absoluteRed] ({pi},0) circle (1.5pt);
\node[absoluteRed,right] at ({pi+5.6},1.4) {$y=\frac14|x-\pi|$};
